mapper.select:
SELECT e.id AS exam_id, e.name AS exam_name, p.name AS paper_name, e.start_time, e.end_time, e.duration, CASE WHEN NOW() < e.start_time THEN 1 WHEN NOW() <= e.end_time THEN 2 ELSE 3 END AS status, e.max_attempts, eu.attempts AS my_attempts, s.id AS sheet_id, s.status AS sheet_status, e.show_score_after, eu.best_score FROM exam_user eu JOIN exam e ON e.id = eu.exam_id LEFT JOIN exam_paper p ON p.id = e.paper_id LEFT JOIN answer_sheet s ON s.id = ( SELECT MAX(x.id) FROM answer_sheet x WHERE x.exam_id = eu.exam_id AND x.user_id = eu.user_id ) WHERE eu.user_id = #{userId}
AND CASE WHEN NOW() < e.start_time THEN 1 WHEN NOW() <= e.end_time THEN 2 ELSE 3 END = #{status}
ORDER BY e.start_time DESC, e.id DESC

mapper.update:
UPDATE exam_user
SET attempts = attempts + 1
WHERE exam_id = #{examId}
  AND user_id = #{userId}
  AND attempts < #{maxAttempts}

UPDATE exam_user
SET best_score = GREATEST(COALESCE(best_score, 0), #{score})
WHERE exam_id = #{examId}
  AND user_id = #{userId}
